mapper.select:
select t.require_value,t.require_value requireValue,t.spec_name,t.spec_name specName,t.modal_id,t.modal_id
modalId,t.spec_cd,t.spec_cd specCd,t.status_cd,t.status_cd statusCd,t.param_id,t.param_id paramId
from dt_modal_param t
where 1 =1

    and t.require_value= #{requireValue}


    and t.spec_name= #{specName}


    and t.modal_id= #{modalId}


    and t.spec_cd= #{specCd}


    and t.status_cd= #{statusCd}


    and t.param_id= #{paramId}

order by t.create_time desc

    limit #{page}, #{row}

